from Crypto.Util.number import *

flag = b"XXX"
p = getPrime(512)
q = getPrime(512)
n = p * q
e = 65537
d = inverse(e, (p - 1) * (q - 1))
c = pow(bytes_to_long(flag), e, n)
p_high = p >> 220
print(f"n = {n}")
print(f"c = {c}")
print(f"e = {e}")
print(f"p_high = {p_high}")

